const W=50,H=50,canvas=document.getElementById('mapCanvas'),wrap=document.getElementById('canvasWrap'),ctx=canvas.getContext('2d');
let seed=741926,world=[],explored=new Set(),visible=new Set(),units=[],cities=[],selected=null,resources={food:8,wood:5,stone:3,culture:0},turn=1,score=0,zoom=1,pan={x:25,y:25},drag=null,gameOver=false,logs=[],kingdom='Mossvale',toastTimer;
const names=['The Verdant Reach','Mosswhisper Vale','The Green March','Fernwood Basin','Cloverfield'];
function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function noise(x,y){let v=Math.sin(x*0.19+Math.sin(y*.13)*2.1)*.18+Math.cos(y*.17+x*.07)*.18+Math.sin((x+y)*.09)*.15+Math.cos(x*.055-y*.11)*.13+rand()*.16;return v+.48}
function makeWorld(){world=[];for(let y=0;y<H;y++){let row=[];for(let x=0;x<W;x++){let n=noise(x,y);let edge=Math.min(x,y,W-1-x,H-1-y);n+=Math.max(0,5-edge)*-.055;let t=n<.34?'water':n<.43?'shore':n>.78?'mountain':n>.66?'hill':rand()<.42?'forest':'plain';row.push({t,variation:rand(),resource:rand()<.10?(rand()<.52?'berries':'stone'):null,owner:null,improvement:null})}world.push(row)}
// Ensure a generous, fertile starting basin.
for(let y=21;y<=29;y++)for(let x=21;x<=29;x++){let t=world[y][x];if(t.t==='water'||t.t==='shore'||t.t==='mountain')t.t='plain';else if((x+y)%5===0)t.t='forest'}
}
const key=(x,y)=>x+','+y;const inside=(x,y)=>x>=0&&y>=0&&x<W&&y<H;const tile=(x,y)=>inside(x,y)?world[y][x]:null;
function reveal(x,y,r=4){for(let yy=Math.max(0,y-r);yy<=Math.min(H-1,y+r);yy++)for(let xx=Math.max(0,x-r);xx<=Math.min(W-1,x+r);xx++)if(Math.abs(xx-x)+Math.abs(yy-y)<=r+1)explored.add(key(xx,yy))}
function updateVision(){visible.clear();for(const u of units)reveal(u.x,u.y);for(const c of cities)reveal(c.x,c.y,5);for(const k of explored){const [x,y]=k.split(',').map(Number);if(units.some(u=>Math.abs(u.x-x)+Math.abs(u.y-y)<=4)||cities.some(c=>Math.abs(c.x-x)+Math.abs(c.y-y)<=5))visible.add(k)}}
function initGame(){seed=741926+Math.floor(Math.random()*999999);makeWorld();explored.clear();visible.clear();units=[];cities=[];resources={food:8,wood:5,stone:3,culture:0};turn=1;score=0;gameOver=false;logs=[];selected=null;kingdom='Mossvale';let p={x:25,y:25};units.push({id:1,type:'settler',name:'Pioneer',x:p.x,y:p.y,moves:2,hp:3});units.push({id:2,type:'scout',name:'Pathfinder',x:p.x+1,y:p.y,moves:2,hp:3});updateVision();pan={x:25,y:25};addLog('A new story begins. Your people arrive in a green and promising land.','🌱');addLog('Choose a clearing and found your first village.','⌂');document.getElementById('regionName').textContent=names[Math.floor(rand()*names.length)];selectEntity(units[0]);refresh();draw()}
function addLog(text,icon='•'){logs.unshift({text,icon});logs=logs.slice(0,6);document.getElementById('feed').innerHTML=logs.map(e=>`<div class="feed-item"><i>${e.icon}</i><span>${e.text}</span></div>`).join('')}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function selectEntity(entity){selected=entity;refresh();draw()}
function entityAt(x,y){return units.find(u=>u.x===x&&u.y===y)||cities.find(c=>c.x===x&&c.y===y)}
function cityAt(x,y){return cities.find(c=>c.x===x&&c.y===y)}
function canFound(u){return u?.type==='settler'&&u.moves>0&&tile(u.x,u.y)?.t!=='water'&&tile(u.x,u.y)?.t!=='shore'&&!cities.some(c=>Math.abs(c.x-u.x)+Math.abs(c.y-u.y)<7)}
function costText(cost){return Object.entries(cost).map(([k,v])=>`${v} ${k}`).join(' · ')}
function hasCost(cost){return Object.entries(cost).every(([k,v])=>resources[k]>=v)}
function spend(cost){for(const [k,v] of Object.entries(cost))resources[k]-=v}
function foundCity(u){if(!canFound(u)){toast('Choose open land at least 7 tiles from another village.');return}const c={id:Date.now(),type:'city',name:['Willowmere','Acornstead','Sunhollow','Thistleford','Brookrest'][cities.length%5],x:u.x,y:u.y,buildings:[],pop:1};cities.push(c);units=units.filter(a=>a!==u);tile(c.x,c.y).owner=c.id;selectEntity(c);updateVision();addLog(`${c.name} is founded. A home for generations to come!`,'🏘️');toast(`${c.name} founded!`);refresh();draw()}
const BUILDINGS=[{id:'farm',name:'Granary',icon:'🌾',cost:{wood:3},yield:'Harvest +2 food',desc:'Store enough to feed a growing town.'},{id:'lumber',name:'Lumber camp',icon:'🪵',cost:{stone:2},yield:'Harvest +2 timber',desc:'Turn the surrounding forest into timber.'},{id:'quarry',name:'Quarry',icon:'🪨',cost:{wood:3},yield:'Harvest +1 stone',desc:'Gather stone for future projects.'},{id:'shrine',name:'Story shrine',icon:'✨',cost:{wood:2,stone:1},yield:'Harvest +2 culture',desc:'Your people build a legacy worth remembering.'}];
function build(c,id){const b=BUILDINGS.find(a=>a.id===id);if(!b||c.buildings.includes(id)||!hasCost(b.cost))return;spend(b.cost);c.buildings.push(id);score+=12;addLog(`${b.name} rises in ${c.name}. ${b.yield}.`,'🔨');toast(`${b.name} complete! +12 realm score`);refresh();draw()}
function spawnWorker(c){const cost={food:4,wood:2};if(!hasCost(cost)){toast('You need 4 food and 2 timber.');return}spend(cost);const spots=[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy])=>({x:c.x+dx,y:c.y+dy})).filter(p=>inside(p.x,p.y)&&tile(p.x,p.y).t!=='water'&&!entityAt(p.x,p.y));if(!spots.length){toast('No room beside this village.');return}const p=spots[0],u={id:Date.now(),type:'worker',name:'Builder',x:p.x,y:p.y,moves:2,hp:2};units.push(u);updateVision();selectEntity(u);addLog(`A builder sets out from ${c.name}.`,'🧑‍🌾');refresh();draw()}

function refresh(){document.getElementById('turn').textContent=turn;document.getElementById('food').textContent=resources.food;document.getElementById('wood').textContent=resources.wood;document.getElementById('stone').textContent=resources.stone;document.getElementById('culture').textContent=resources.culture;document.getElementById('kingdomName').textContent=kingdom;const dots=document.getElementById('turnDots');dots.innerHTML=Array.from({length:20},(_,i)=>`<i class="${i<turn-1?'done':''}"></i>`).join('');
let food=1+cities.length*2,wood=1,stone=0,culture=0;for(const c of cities)for(const id of c.buildings){if(id==='farm')food+=2;if(id==='lumber')wood+=2;if(id==='quarry')stone+=1;if(id==='shrine')culture+=2}for(const row of world)for(const t of row)if(t.improvement){if(t.improvement==='farm')food+=2;if(t.improvement==='grove')wood+=2}
document.getElementById('yield').textContent=`+${food} food · +${wood} timber${stone?` · +${stone} stone`:''}${culture?` · +${culture} culture`:''}`;document.getElementById('scoreLabel').textContent=`${Math.min(100,score)} / 100`;document.getElementById('progress').style.width=`${Math.min(100,score)}%`;document.getElementById('objectiveText').textContent=cities.length===0?'Found your first village, then grow your kingdom.':score>=100?'Your little kingdom is flourishing. Hold on to your legacy!':`${cities.length} ${cities.length===1?'village':'villages'} · ${BUILDINGS.reduce((n,b)=>n+cities.filter(c=>c.buildings.includes(b.id)).length,0)} projects complete · Explore to discover more.`;
const box=document.getElementById('selection');if(!selected){box.innerHTML='<div class="empty-selection">Select your people or a village on the map to see what they can do.</div>';return}
if(selected.type==='city'){const c=selected;let buttons=BUILDINGS.map(b=>{const done=c.buildings.includes(b.id),disabled=done||!hasCost(b.cost);return `<button class="action-btn" data-build="${b.id}" ${disabled?'disabled':''}>${done?'✓ ':b.icon+' '}${b.name}<span>${done?'Complete':costText(b.cost)} · ${b.yield}</span></button>`}).join('');box.innerHTML=`<div class="selected-unit"><div class="unit-avatar">🏘️</div><div><div class="unit-name">${c.name}</div><div class="unit-sub">Village · population ${c.pop}</div></div><div class="unit-hp">+2🌾</div></div><div class="section-label">Village projects</div><div class="actions">${buttons}<button class="action-btn" data-worker="1" ${hasCost({food:4,wood:2})?'':'disabled'}>🧑‍🌾 Hire builder<span>4 food · 2 timber</span></button></div>`;box.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>build(c,b.dataset.build));box.querySelector('[data-worker]').onclick=()=>spawnWorker(c);return}
const u=selected;let avatar=u.type==='settler'?'🧳':u.type==='scout'?'🧭':'🧑‍🌾';let role=u.type==='settler'?'Settler':u.type==='scout'?'Scout':'Builder';let unitActions='';if(u.type==='settler')unitActions=`<button class="action-btn primary" data-found ${canFound(u)?'':'disabled'}>⌂ Found village<span>${canFound(u)?'Settle this clearing':'Move to open ground'}</span></button><button class="action-btn" data-wait ${u.moves?'':'disabled'}>◷ Rest here<span>End this unit’s turn</span></button>`;else if(u.type==='worker'){const t=tile(u.x,u.y),imp=t?.improvement;let typ=t?.t==='forest'?'grove':'farm',label=typ==='grove'?'Plant a grove':'Build a farm',emoji=typ==='grove'?'🌲':'🌾';unitActions=`<button class="action-btn primary" data-improve ${imp||!hasCost({wood:2})?'disabled':''}>${imp?'✓ Improved':emoji+' '+label}<span>${imp?(imp==='farm'?'+2 food':' +2 timber'):'2 timber · permanent yield'}</span></button><button class="action-btn" data-wait ${u.moves?'':'disabled'}>◷ Rest here<span>End this unit’s turn</span></button>`}else unitActions=`<button class="action-btn" data-wait ${u.moves?'':'disabled'}>⚑ Keep watch<span>Stay alert in this place</span></button>`;
box.innerHTML=`<div class="selected-unit"><div class="unit-avatar">${avatar}</div><div><div class="unit-name">${u.name}</div><div class="unit-sub">${role} · ${u.moves} moves left</div></div><div class="unit-hp">❤ ${u.hp}</div></div><div class="section-label">Orders</div><div class="actions">${unitActions}</div>`;box.querySelector('[data-found]')?.addEventListener('click',()=>foundCity(u));box.querySelector('[data-wait]')?.addEventListener('click',()=>{u.moves=0;refresh();toast(`${u.name} is resting.`)});box.querySelector('[data-improve]')?.addEventListener('click',()=>improve(u));}
function improve(u){const t=tile(u.x,u.y);if(!t||t.improvement||!hasCost({wood:2}))return;spend({wood:2});t.improvement=t.t==='forest'?'grove':'farm';score+=5;u.moves=0;addLog(`${u.name} improved the land. Your harvest will grow.`,'🌱');toast('Land improved! +5 realm score');refresh();draw()}
function resize(){const r=wrap.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*dpr));canvas.height=Math.max(1,Math.floor(r.height*dpr));ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function cellSize(){const w=wrap.clientWidth,h=wrap.clientHeight;return Math.max(8,Math.min(26,Math.min(w/31,h/25)*zoom))}
function draw(){if(!wrap||!canvas.width)return;const dpr=Math.min(window.devicePixelRatio||1,2),cw=canvas.width/dpr,ch=canvas.height/dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,cw,ch);const s=cellSize(),ox=cw/2-pan.x*s,oy=ch/2-pan.y*s;ctx.fillStyle='#b9d1c5';ctx.fillRect(0,0,cw,ch);const x0=Math.max(0,Math.floor(-ox/s)-1),x1=Math.min(W-1,Math.ceil((cw-ox)/s)+1),y0=Math.max(0,Math.floor(-oy/s)-1),y1=Math.min(H-1,Math.ceil((ch-oy)/s)+1);
for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){const k=key(x,y),t=world[y][x],px=ox+x*s,py=oy+y*s;if(!explored.has(k)){ctx.fillStyle='#294a4d';ctx.fillRect(px,py,s+.5,s+.5);if((x*13+y*7)%29===0){ctx.fillStyle='#345659';ctx.fillRect(px+s*.35,py+s*.4,2,2)}continue}paintTile(t,x,y,px,py,s);if(!visible.has(k)){ctx.fillStyle='#233d3b99';ctx.fillRect(px,py,s,s);continue}if(t.improvement)drawImprovement(t,px,py,s);const owner=cities.find(c=>Math.abs(c.x-x)+Math.abs(c.y-y)<=4);if(owner){ctx.strokeStyle='#e7e9ba88';ctx.lineWidth=Math.max(1,s*.075);ctx.strokeRect(px+1,py+1,s-2,s-2)}if(t.resource&&s>14){ctx.font=`${Math.round(s*.48)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(t.resource==='berries'?'🍓':'✦',px+s*.77,py+s*.72)}}
// Grid lines
ctx.strokeStyle='#315f5530';ctx.lineWidth=.6;for(let x=x0;x<=x1+1;x++){ctx.beginPath();ctx.moveTo(ox+x*s,oy+y0*s);ctx.lineTo(ox+x*s,oy+(y1+1)*s);ctx.stroke()}for(let y=y0;y<=y1+1;y++){ctx.beginPath();ctx.moveTo(ox+x0*s,oy+y*s);ctx.lineTo(ox+(x1+1)*s,oy+y*s);ctx.stroke()}
// Cities then units. Icons remain crisp at all zoom levels.
for(const c of cities)if(visible.has(key(c.x,c.y)))drawEntity(c,ox+c.x*s,oy+c.y*s,s);
for(const u of units)if(visible.has(key(u.x,u.y)))drawEntity(u,ox+u.x*s,oy+u.y*s,s);
if(selected&&selected.x!==undefined&&visible.has(key(selected.x,selected.y))){ctx.strokeStyle=selected.type==='city'?'#f8e6a3':'#fff';ctx.lineWidth=2;ctx.strokeRect(ox+selected.x*s+1,oy+selected.y*s+1,s-2,s-2)}
if(hover&&inside(hover.x,hover.y)&&visible.has(key(hover.x,hover.y))){ctx.strokeStyle='#fff9';ctx.lineWidth=1.5;ctx.strokeRect(ox+hover.x*s+1.5,oy+hover.y*s+1.5,s-3,s-3)}
}
function paintTile(t,x,y,px,py,s){let palettes={plain:['#dfc878','#e5cd80','#d9be70'],forest:['#57946a','#639e70','#4e8962'],hill:['#9ca875','#a7b17c','#909d6c'],mountain:['#858f80','#929b8d','#788476'],water:['#659eaa','#70aab3','#5b939f'],shore:['#c9c78e','#d1cb91','#c2bd83']};let colors=palettes[t.t],color=colors[Math.floor(t.variation*colors.length)];ctx.fillStyle=color;ctx.fillRect(px,py,s+.5,s+.5);if(s<10)return;ctx.save();if(t.t==='forest'){const count=s>20?3:2;for(let i=0;i<count;i++){const tx=px+s*(.25+((i*37+x*13+y*7)%55)/100),ty=py+s*(.27+((i*21+x*7+y*13)%45)/100),r=s*(s>20?.18:.23);ctx.fillStyle='#397451';ctx.beginPath();ctx.moveTo(tx,ty-r);ctx.lineTo(tx-r*.78,ty+r*.48);ctx.lineTo(tx+r*.78,ty+r*.48);ctx.closePath();ctx.fill();ctx.fillStyle='#78ab71';ctx.beginPath();ctx.moveTo(tx,ty-r*.72);ctx.lineTo(tx-r*.5,ty+r*.18);ctx.lineTo(tx+r*.5,ty+r*.18);ctx.closePath();ctx.fill();ctx.fillStyle='#755c43';ctx.fillRect(tx-1,ty+r*.35,2,r*.46)}}else if(t.t==='hill'||t.t==='mountain'){let n=t.t==='hill'?2:3;for(let i=0;i<n;i++){let hx=px+s*(.15+i*.3),hy=py+s*(.62-(i%2)*.17),r=s*(t.t==='hill'?.28:.36);ctx.fillStyle=t.t==='hill'?'#83956c':'#737f77';ctx.beginPath();ctx.moveTo(hx-r,hy+r*.38);ctx.lineTo(hx,hy-r);ctx.lineTo(hx+r,hy+r*.38);ctx.closePath();ctx.fill();ctx.fillStyle=t.t==='hill'?'#bec18a':'#d6d9cd';ctx.beginPath();ctx.moveTo(hx,hy-r);ctx.lineTo(hx-r*.28,hy-r*.1);ctx.lineTo(hx+r*.08,hy-r*.04);ctx.closePath();ctx.fill()}}else if(t.t==='water'){ctx.strokeStyle='#a5d0c3aa';ctx.lineWidth=1;for(let i=0;i<2;i++){let yy=py+s*(.34+i*.31),xx=px+s*(.17+((x*7+y*11+i*23)%32)/100);ctx.beginPath();ctx.moveTo(xx,yy);ctx.quadraticCurveTo(xx+s*.14,yy-2,xx+s*.28,yy);ctx.stroke()}}else{ctx.fillStyle='#a8b86d88';for(let i=0;i<3;i++){let gx=px+s*((i*31+x*13+y*3)%80+10)/100,gy=py+s*((i*17+y*11+x*5)%80+10)/100;ctx.fillRect(gx,gy,1.3,3)}}ctx.restore()}
function drawImprovement(t,px,py,s){ctx.fillStyle='#f7f0d7';ctx.beginPath();ctx.arc(px+s*.5,py+s*.5,s*.25,0,Math.PI*2);ctx.fill();ctx.font=`${Math.round(s*.5)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(t.improvement==='farm'?'🌾':'🌳',px+s*.5,py+s*.5)}
function drawEntity(e,px,py,s){const city=e.type==='city',emoji=city?'🏘️':e.type==='settler'?'🧳':e.type==='scout'?'🧭':'🧑‍🌾';ctx.fillStyle=city?'#f4e3a8':'#fff5dc';ctx.beginPath();ctx.arc(px+s*.5,py+s*.49,s*.39,0,Math.PI*2);ctx.fill();ctx.strokeStyle=city?'#946c39':'#476f53';ctx.lineWidth=1.4;ctx.stroke();ctx.font=`${Math.round(Math.min(s*.66,25))}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(emoji,px+s*.5,py+s*.49);if(city&&s>16){ctx.fillStyle='#24483b';ctx.font=`700 ${Math.max(8,Math.min(10,s*.32))}px 'DM Sans',sans-serif`;ctx.textAlign='center';ctx.textBaseline='top';ctx.fillText(e.name,px+s*.5,py+s*.83)}}

let hover=null;
// Score a little for each new patch of land discovered.
const rawReveal=reveal;reveal=function(x,y,r=4){const before=explored.size;rawReveal(x,y,r);score+=(explored.size-before)*.12};
function mapPoint(clientX,clientY){const r=canvas.getBoundingClientRect(),s=cellSize(),ox=r.width/2-pan.x*s,oy=r.height/2-pan.y*s;return{x:Math.floor((clientX-r.left-ox)/s),y:Math.floor((clientY-r.top-oy)/s)}}
function moveUnit(u,x,y){if(gameOver||!u||u.moves<=0)return;const d=Math.abs(u.x-x)+Math.abs(u.y-y);if(d!==1){toast('Move one tile at a time.');return}if(!inside(x,y)||tile(x,y).t==='water'||entityAt(x,y)){toast('That tile is blocked.');return}u.x=x;u.y=y;u.moves--;score+=.4;updateVision();selectEntity(u);}
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,panX:pan.x,panY:pan.y,moved:false};canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;if(drag.moved){const s=cellSize();pan.x=drag.panX-dx/s;pan.y=drag.panY-dy/s;draw()}}else{hover=mapPoint(e.clientX,e.clientY);draw();const p=hover;document.getElementById('coords').textContent=inside(p.x,p.y)?`${String(p.x+1).padStart(2,'0')} · ${String(p.y+1).padStart(2,'0')}`:'—'}});
canvas.addEventListener('pointerup',e=>{if(!drag)return;if(!drag.moved){const p=mapPoint(e.clientX,e.clientY);if(inside(p.x,p.y)){const target=entityAt(p.x,p.y);if(target){selectEntity(target)}else if(selected&&selected.type!=='city')moveUnit(selected,p.x,p.y);else{selected=null;refresh();draw()}}}drag=null});canvas.addEventListener('pointercancel',()=>drag=null);
wrap.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(1.7,zoom*(e.deltaY<0?1.1:.91)));draw()},{passive:false});
document.getElementById('zoomIn').onclick=()=>{zoom=Math.min(1.7,zoom*1.15);draw()};document.getElementById('zoomOut').onclick=()=>{zoom=Math.max(.65,zoom/1.15);draw()};document.getElementById('centerMap').onclick=()=>{if(selected&&selected.x!==undefined)pan={x:selected.x,y:selected.y};else pan={x:25,y:25};draw()};
function endTurn(){if(gameOver)return;let food=1+cities.length*2,wood=1,stone=0,culture=0;for(const c of cities)for(const id of c.buildings){if(id==='farm')food+=2;if(id==='lumber')wood+=2;if(id==='quarry')stone+=1;if(id==='shrine')culture+=2}for(const row of world)for(const t of row)if(t.improvement){if(t.improvement==='farm')food+=2;if(t.improvement==='grove')wood+=2}resources.food+=food-cities.length;resources.wood+=wood;resources.stone+=stone;resources.culture+=culture;
for(const c of cities){if(resources.food>=4){resources.food-=4;c.pop++;resources.culture++;score+=3;addLog(`${c.name} welcomes a new family. Population ${c.pop}.`,'👨‍👩‍👧')} }
for(const u of units)u.moves=2;turn++;if(turn>20){turn=20;gameOver=true;refresh();showFinal();return}if(turn===20)addLog('One last season remains. Make it count!','🍂');refresh();draw();}
document.getElementById('endTurn').onclick=endTurn;
window.addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();endTurn();return}if(!selected||selected.type==='city'||gameOver)return;const moves={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]},m=moves[e.key];if(m){e.preventDefault();moveUnit(selected,selected.x+m[0],selected.y+m[1])}});
function modal(icon,title,body,buttons){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-icon">${icon}</div><h2>${title}</h2><div>${body}</div><div class="modal-actions">${buttons}</div></div></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''})}
function showHelp(){modal('🌱','A little world, yours to shape',`<p>You have <b>20 turns</b> to explore this tiny 50 × 50 world and build a thriving kingdom.</p><ul class="help-list"><li><b>Found villages:</b> Select your settler, move to open land, then found a village.</li><li><b>Build:</b> Select a village and spend timber or stone on projects. Each project adds income and realm score.</li><li><b>Explore:</b> Click a unit, then click a neighboring tile. Discoveries add score.</li><li><b>Grow:</b> Villages gather food and timber each season. Food helps your population grow.</li><li><b>Builders:</b> Hire one from a village to improve the tile they stand on.</li></ul><p>Reach <b>100 realm score</b> for a flourishing kingdom—or see what story unfolds after 20 turns.</p>`,`<button class="confirm" id="modalOk">Let’s play</button>`);document.getElementById('modalOk').onclick=()=>document.getElementById('modalRoot').innerHTML=''}
function showFinal(){const grade=score>=100?'A flourishing realm':score>=65?'A growing kingdom':score>=35?'A humble beginning':'A quiet little story';modal(score>=100?'🌳':'📜','Twenty seasons have passed',`<p><b>${grade}</b> — your people will remember what you built together.</p><div class="end-stats"><div><b>${Math.round(score)}</b><span>Realm score</span></div><div><b>${cities.length}</b><span>Villages</span></div><div><b>${Math.round(resources.culture)}</b><span>Culture</span></div><div><b>${explored.size}</b><span>Tiles explored</span></div></div><p>${score>=100?'Your tiny civilization has grown into something remarkable.': 'Every great civilization starts somewhere. See what you can build in another story.'}</p>`,`<button id="reviewBtn">Review map</button><button class="confirm" id="restartBtn">Start a new world ↗</button>`);document.getElementById('reviewBtn').onclick=()=>{document.getElementById('modalRoot').innerHTML='';gameOver=true};document.getElementById('restartBtn').onclick=()=>{document.getElementById('modalRoot').innerHTML='';initGame()}}
document.getElementById('helpBtn').onclick=showHelp;document.getElementById('newBtn').onclick=()=>modal('↻','Begin a new story?',`<p>Your current kingdom will be lost, and a fresh 20-turn world will begin.</p>`,`<button id="cancelNew">Keep playing</button><button class="confirm" id="confirmNew">New world</button>`);document.addEventListener('click',e=>{if(e.target.id==='cancelNew'||e.target.id==='confirmNew')document.getElementById('modalRoot').innerHTML='';if(e.target.id==='confirmNew')initGame()});
document.getElementById('renameBtn').onclick=()=>modal('✎','Name your kingdom',`<p>What will future generations call this place?</p><input id="nameInput" maxlength="18" value="${kingdom}" style="width:100%;padding:11px 12px;border:1px solid #dfe4d5;border-radius:10px;font:700 14px 'DM Sans',sans-serif;outline-color:#829e67">`,`<button id="cancelName">Cancel</button><button class="confirm" id="saveName">Save name</button>`);document.addEventListener('click',e=>{if(e.target.id==='cancelName')document.getElementById('modalRoot').innerHTML='';if(e.target.id==='saveName'){const v=document.getElementById('nameInput').value.trim();if(v)kingdom=v.slice(0,18);document.getElementById('modalRoot').innerHTML='';refresh()}});
new ResizeObserver(resize).observe(wrap);window.addEventListener('resize',resize);initGame();showHelp();
</script></body></html>

