 </style></head><body><div class="app"><header><div class="brand"><div class="brand-mark">🌱</div><div><h1>Little Kingdoms</h1><p>A tiny civilization story</p></div></div><div class="header-right"><div class="turn-pill"><div><div class="turn-label">Turn</div><div class="turn-num"><span id="turn">1</span><span style="color:#a7b49a"> / 20</span></div></div><div class="turn-dots" id="turnDots"></div></div><button class="icon-btn" id="helpBtn" title="How to play">?</button><button class="icon-btn" id="newBtn" title="New kingdom">↻</button></div></header>
 <div class="game-layout"><main class="map-card"><div class="map-head"><div class="region"><span class="pin">⌖</span><span id="regionName">The Verdant Reach</span></div><div class="map-hint">Explore, settle, and thrive for 20 turns</div><div class="map-tools"><button id="zoomOut" title="Zoom out">−</button><button id="zoomIn" title="Zoom in">+</button><button id="centerMap" title="Center map">⌖</button></div></div><div class="canvas-wrap" id="canvasWrap"><canvas id="mapCanvas" aria-label="50 by 50 civilization map"></canvas><div class="map-legend"><span class="legend-item"><i class="legend-color" style="background:#64a46d"></i>Forest</span><span class="legend-item"><i class="legend-color" style="background:#dfc778"></i>Plains</span><span class="legend-item"><i class="legend-color" style="background:#5e9aab"></i>Water</span><span class="legend-item">⌂ Your land</span></div><div class="map-coords" id="coords">—</div></div></main>
 <aside class="sidebar"><section class="side-card"><div class="kingdom-name"><div class="empire-title" id="kingdomName">Mossvale</div><button class="edit-name" id="renameBtn">✎ RENAME</button></div><div class="resource-grid"><div class="resource"><div class="res-icon">🌾</div><div><div class="res-value" id="food">8</div><div class="res-label">Food</div></div></div><div class="resource"><div class="res-icon">🪵</div><div><div class="res-value" id="wood">5</div><div class="res-label">Timber</div></div></div><div class="resource"><div class="res-icon">🪨</div><div><div class="res-value" id="stone">3</div><div class="res-label">Stone</div></div></div><div class="resource"><div class="res-icon">✨</div><div><div class="res-value" id="culture">0</div><div class="res-label">Culture</div></div></div></div><div class="yield-note"><span>Next harvest</span><b id="yield">+2 food · +1 timber</b></div></section>
 <section class="side-card action-card"><div class="section-label">Your people</div><div id="selection"></div></section><section class="objective"><div class="objective-top"><span>🌿 &nbsp;Build a thriving realm</span><span id="scoreLabel">0 / 100</span></div><div class="progress"><i id="progress"></i></div><p id="objectiveText">Found your first village, then grow your kingdom.</p></section><section class="side-card feed-card"><div class="feed-head"><div class="section-label">Kingdom chronicle</div><span class="feed-clear">LATEST NEWS</span></div><div class="feed" id="feed"></div></section><button class="end-turn" id="endTurn"><div><strong>End turn</strong><small>Collect yields &amp; advance the season</small></div><span class="arrow">→</span></button></aside></div><div class="bottomline"><span>A 50 × 50 world, shaped by your choices.</span><span class="keys">Click to select · WASD / arrows to move · Space to end turn</span></div></div><div class="toast" id="toast"></div><div id="modalRoot"></div><script>
+const W=50,H=50,canvas=document.getElementById('mapCanvas'),wrap=document.getElementById('canvasWrap'),ctx=canvas.getContext('2d');
+let seed=741926,world=[],explored=new Set(),visible=new Set(),units=[],cities=[],selected=null,resources={food:8,wood:5,stone:3,culture:0},turn=1,score=0,zoom=1,pan={x:25,y:25},drag=null,hover=null,gameOver=false,logs=[],kingdom='Mossvale',toastTimer;
+const names=['The Verdant Reach','Mosswhisper Vale','The Green March','Fernwood Basin','Cloverfield'];
+function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
+function noise(x,y){return .48+Math.sin(x*.19+Math.sin(y*.13)*2.1)*.18+Math.cos(y*.17+x*.07)*.18+Math.sin((x+y)*.09)*.15+Math.cos(x*.055-y*.11)*.13+rand()*.16}
+function makeWorld(){world=[];for(let y=0;y<H;y++){let row=[];for(let x=0;x<W;x++){let n=noise(x,y)+Math.max(0,5-Math.min(x,y,W-1-x,H-1-y))*-.055;let t=n<.34?'water':n<.43?'shore':n>.78?'mountain':n>.66?'hill':rand()<.42?'forest':'plain';row.push({t,variation:rand(),resource:rand()<.1?(rand()<.52?'berries':'stone'):null,improvement:null})}world.push(row)}for(let y=21;y<=29;y++)for(let x=21;x<=29;x++){let t=world[y][x];if(['water','shore','mountain'].includes(t.t))t.t='plain';else if((x+y)%5===0)t.t='forest'}}
+const key=(x,y)=>x+','+y,inside=(x,y)=>x>=0&&y>=0&&x<W&&y<H,tile=(x,y)=>inside(x,y)?world[y][x]:null;
+function reveal(x,y,r=4){let before=explored.size;for(let yy=Math.max(0,y-r);yy<=Math.min(H-1,y+r);yy++)for(let xx=Math.max(0,x-r);xx<=Math.min(W-1,x+r);xx++)if(Math.abs(xx-x)+Math.abs(yy-y)<=r+1)explored.add(key(xx,yy));score+=(explored.size-before)*.12}
+function updateVision(){visible.clear();for(const u of units)reveal(u.x,u.y);for(const c of cities)reveal(c.x,c.y,5);for(const k of explored){let [x,y]=k.split(',').map(Number);if(units.some(u=>Math.abs(u.x-x)+Math.abs(u.y-y)<=4)||cities.some(c=>Math.abs(c.x-x)+Math.abs(c.y-y)<=5))visible.add(k)}}
+function addLog(text,icon='•'){logs.unshift({text,icon});logs=logs.slice(0,6);document.getElementById('feed').innerHTML=logs.map(e=>`<div class="feed-item"><i>${e.icon}</i><span>${e.text}</span></div>`).join('')}
+function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
+function selectEntity(e){selected=e;refresh();draw()}
+function entityAt(x,y){return units.find(u=>u.x===x&&u.y===y)||cities.find(c=>c.x===x&&c.y===y)}
+function canFound(u){return u?.type==='settler'&&u.moves>0&&!['water','shore'].includes(tile(u.x,u.y)?.t)&&!cities.some(c=>Math.abs(c.x-u.x)+Math.abs(c.y-u.y)<7)}
+const BUILDINGS=[{id:'farm',name:'Granary',icon:'🌾',cost:{wood:3},yield:'+2 food'},{id:'lumber',name:'Lumber camp',icon:'🪵',cost:{stone:2},yield:'+2 timber'},{id:'quarry',name:'Quarry',icon:'🪨',cost:{wood:3},yield:'+1 stone'},{id:'shrine',name:'Story shrine',icon:'✨',cost:{wood:2,stone:1},yield:'+2 culture'}];
+function hasCost(c){return Object.entries(c).every(([k,v])=>resources[k]>=v)}function spend(c){for(const [k,v] of Object.entries(c))resources[k]-=v}function costText(c){return Object.entries(c).map(([k,v])=>`${v} ${k}`).join(' · ')}
+function initGame(){seed=741926+Math.floor(Math.random()*999999);makeWorld();explored.clear();visible.clear();units=[];cities=[];resources={food:8,wood:5,stone:3,culture:0};turn=1;score=0;gameOver=false;logs=[];selected=null;kingdom='Mossvale';units.push({id:1,type:'settler',name:'Pioneer',x:25,y:25,moves:2,hp:3},{id:2,type:'scout',name:'Pathfinder',x:26,y:25,moves:2,hp:3});updateVision();pan={x:25,y:25};addLog('A new story begins. Your people arrive in a green and promising land.','🌱');addLog('Choose a clearing and found your first village.','⌂');document.getElementById('regionName').textContent=names[Math.floor(rand()*names.length)];selectEntity(units[0]);refresh();draw()}
+function foundCity(u){if(!canFound(u)){toast('Choose open land at least 7 tiles from another village.');return}let c={id:Date.now(),type:'city',name:['Willowmere','Acornstead','Sunhollow','Thistleford','Brookrest'][cities.length%5],x:u.x,y:u.y,buildings:[],pop:1};cities.push(c);score+=15;units=units.filter(a=>a!==u);selectEntity(c);updateVision();addLog(`${c.name} is founded. A home for generations to come!`,'🏘️');toast(`${c.name} founded! +15 realm score`);refresh();draw()}
+function build(c,id){let b=BUILDINGS.find(a=>a.id===id);if(!b||c.buildings.includes(id)||!hasCost(b.cost))return;spend(b.cost);c.buildings.push(id);score+=12;addLog(`${b.name} rises in ${c.name}. Your harvest will grow.`,'🔨');toast(`${b.name} complete! +12 realm score`);refresh();draw()}
+function improve(u){let t=tile(u.x,u.y);if(!t||t.improvement||!hasCost({wood:2}))return;spend({wood:2});t.improvement=t.t==='forest'?'grove':'farm';score+=5;u.moves=0;addLog('Your builder improved the land.','🌱');toast('Land improved! +5 realm score');refresh();draw()}
+function spawnWorker(c){if(!hasCost({food:4,wood:2})){toast('You need 4 food and 2 timber.');return}spend({food:4,wood:2});let spots=[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy])=>({x:c.x+dx,y:c.y+dy})).filter(p=>inside(p.x,p.y)&&tile(p.x,p.y).t!=='water'&&!entityAt(p.x,p.y));if(!spots.length){toast('No room beside this village.');return}let p=spots[0],u={id:Date.now(),type:'worker',name:'Builder',x:p.x,y:p.y,moves:2,hp:2};units.push(u);updateVision();selectEntity(u);addLog(`A builder sets out from ${c.name}.`,'🧑‍🌾')}
+function yields(){let food=1+cities.length*2,wood=1,stone=0,culture=0;for(const c of cities)for(const id of c.buildings){if(id==='farm')food+=2;if(id==='lumber')wood+=2;if(id==='quarry')stone++;if(id==='shrine')culture+=2}for(const row of world)for(const t of row)if(t.improvement){if(t.improvement==='farm')food+=2;if(t.improvement==='grove')wood+=2}return{food,wood,stone,culture}}

